package io.knowledgebrain.learning;
import java.time.*;import java.util.*;import org.junit.jupiter.api.Test;import static org.junit.jupiter.api.Assertions.*;
class GitHubReferenceValidationTest {
 @Test void exactOwnerImportedFactAcceptsBotButRejectsEchoAndMutableOrPrivateSources(){var ids=new UuidV7(Clock.systemUTC());UUID space=ids.next(),actor=ids.next(),repo=ids.next(),commit=ids.next();String sha="a".repeat(40),url="https://github.com/octocat/Hello-World/commit/"+sha;var valid=new GitHubReferenceClient.Reference(space,actor,repo,commit,"octocat/Hello-World",sha,"Pinned subject","dependabot[bot]","2020-01-01T00:00:00Z","2026-11-01T00:00:00Z",url,"PRIVATE","PUBLIC",1);assertDoesNotThrow(()->GitHubReferenceClient.validate(valid,space,repo,commit,actor));assertThrows(RuntimeException.class,()->GitHubReferenceClient.validate(valid,space,repo,commit,ids.next()));for(String visibility:List.of("PRIVATE","PUBLIC")){var bad=new GitHubReferenceClient.Reference(space,actor,repo,commit,"octocat/Hello-World",sha,"subject",null,"2020-01-01T00:00:00Z","2026-11-01T00:00:00Z",url,visibility,visibility,1);assertThrows(RuntimeException.class,()->GitHubReferenceClient.validate(bad,space,repo,commit,actor));}var bad=new GitHubReferenceClient.Reference(space,actor,repo,commit,"octocat/Hello-World",sha,"subject",null,"2020-01-01T00:00:00Z","2026-11-01T00:00:00Z","https://evil.test/","PRIVATE","PUBLIC",1);assertThrows(RuntimeException.class,()->GitHubReferenceClient.validate(bad,space,repo,commit,actor));}
}
